style.css:
@-moz-document domain("survev.io") {
#background
  {
    background-image: url(https://vignette.wikia.nocookie.net/animal-jam-clans-1/images/7/7d/Blue_mountains_animation_by_grayamaroq-d9vbn8y.gif/revision/latest?cb=20160721075412) !important;
  }

  #start-row-header
  {
    background-image: url(https://i.imgur.com/I4uYvnX.png) !important;
  }

  #start-top-left
  {
    visibility: visible !important;
  }

  #featured-streamers
  {
    visibility: visible !important;
  }

  #start-bottom-left
  {
    visibility: visible !important;
  }

  #start-bottom-middle
  {
    visibility: visible !important;
  }
  /*Kill Leader Icon Start*/
  #ui-kill-leader-icon
  {
  background-color: #0006;
  background-image: url(https://i.imgur.com/1PmSqQx.png)
  }

  #ui-kill-leader-wrapper
  {
  color: #ffe741;
  position: absolute;
  right: 112px;
  top: 0;
  }
/*Kill Leader End*/
/*Also known as timer above map*/ 
  #ui-map-info
  {
   color: #67e84c;
  }
   
   .gas-icon
   {
    background-image: url(https://i.imgur.com/NNGPVcu.png)
   }

   .danger-icon
   {
    background-image: url(https://i.imgur.com/PDEQQ4w.png)
   }
  .menu-option
  {
    border-radius: 0px !important;
    border-color: #40436d !important;
  }

  .btn-green
  {
    border-bottom: 0px !important;
    background: #6c70b7 !important;
    color: #FFFFFF !important;
    box-shadow: inset 0 -2px #202020;
  }

  .btn-team-option
  {
    border-bottom: 0px !important;
    background: #6c70b7 !important;
    color: #fff !important;
    box-shadow: inset 0 -2px #202020;
  }

  .account-details-button-wrapper
  {
    border-bottom: 0px !important;
    background: #6c70b7 !important;
    color: #40436d !important;
    box-shadow: inset 0 -2px #202020 !important;
  }
  
  
/* Start Of Loadout Editing */ 

  #modal-customize-body 
  { 
  background-color: #6c70b7;
  color: #000;
  height: auto;
  }

/*Top of the loadout header, probably should be darker than middle menu*/
  #modal-customize-header
  {  
  background-color: #40436d;
  color: #fff;
  height: 122px;
  }
/*Bottom of loadout header*/
  #modal-customize-footer
  {
  background-color: #40436d;
  color: #fff;
  height: 56px;  
  }    
  .modal-content-right
  {
  background: #40436d;
  border: 6px solid rgba(0,0,0,.5);
  border-radius: 5px;
  bottom: 0;
  display: none;
  pointer-events: initial;
  position: fixed;
  right: 0;
  width: 330px;
  }
 /*Finish Loadout Editing*/   


 /* Start of Keybind Menu Editing*/
  #ui-modal-keybind-body
  { 
   background-color: #40436d;
   color: #000;
  }
  
  #ui-modal-keybind-header
  {
  background-color: #40436d;
  }
  
  #ui-modal-keybind-footer
  {
  background-color: #40436d;
  color: #fff;
  height: 60px;
  display: flex;
  justify-content: space-between;
  }
/*Finish keybind Editing*/

/*In-game Menu Configuration*/
 .btn-game-menu
 { 
  text-align: center;
  line-height: 38px;
  display: block;
  width: 100%;
  height: 40px;
  border: 0px;
  border-bottom-width: 0px;
  border-bottom-style: none;
  border-bottom-color: #6c70b7;
  border-radius: 5px;
  box-sizing: border-box;
  position: relative;
  margin: 5px auto;
  margin-top: 5px;
  color: #fff;
  font-size: 16px;
  text-shadow: 0 1px 2px #000;
  background-color: #6c70b7;
  border-bottom: 2px solid #6c70b7;
  box-shadow: inset 0 -2px #6c70b7;
  background-repeat: no-repeat;
  cursor: pointer;
  }
/*Finish In-game menu config*/

/*Start In-game Death Menu*/
  .ui-stats-header-title
  {
  font-weight: 700;
  font-size: 48px;
  margin: 10px;
  color: red;
  }
  
  #ui-stats-logo
  {
  background-image: url(https://i.imgur.com/I4uYvnX.png);
  background-repeat: no-repeat;
  background-size: 264px;
  background-position: center;
  height: 125px;
  position: absolute;
  left: 20px;
  top: 8px;
  width: 264px;
  }
/*End in-game Death Menu*/

/*Start Spectate Menus*/
  #ui-spectate-options
  {
  position: relative;
  color: #fff;
  font-size: 16px;
  text-shadow: 0 1px 2px rgba(255, 255, 255, .25);
  background: #6c70b7;
  border-bottom: 2px solid #6c70b7;
  box-shadow: inset 0 -2px #6c70b7;
  cursor: pointer;
  }


  
  #btn-pass-locked
  {
    border-bottom: 0px !important;
    background: #6c70b7 !important;
    color: #40436d !important;
    box-shadow: inset 0 -2px #202020;
  }

  #btn-customize
  {
    border-bottom: 0px !important;
    background: #6c70b7 !important;
    background-image: url(https://survev.io/img/emotes/surviv.svg) !important;
    background-position: 8px 5px !important;
    background-repeat: no-repeat !important;
    background-size: 28px !important;
    color: #40436d!important;
    box-shadow: inset 0 -2px #202020;
  }

  #btn-help
  {
    border-bottom: 0px !important;
  }
}
